// logoConfig.js

// Full base64 data URI for the logo
const LOGO_BASE64 =
  "data:image/png;base64,";

// Export for Node.js / backend use
export default LOGO_BASE64;

// Also make it global for the frontend (since we load it via a script tag)
if (typeof window !== "undefined") {
  window.LOGO_BASE64 = LOGO_BASE64;
}
